{
  "url": "https://spaceweather.ac.cn/upload/88d49102-e306-406d-a38c-a9281981c7b1/20221031/77151667195575100.pdf",
  "prompt": "What is this document (title, authors, year)? Extract quantitative SIR statistics: SIR occurrence per year, shock association fractions (forward/reverse/pair) at 1 AU and at other heliocentric distances (0.72 AU, 5.3 AU), peak Pt, peak Np, peak B, speed increase. Quote verbatim."
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; T=/home/scabot/.claude/projects/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/tool-results; cp $T/webfetch-1792192448535-i7o80l.pdf $S/pdfs/swac.pdf; cd $S && python3 -I scripts/ex.py pdfs/swac.pdf txt/swac.txt; wc -c txt/swac.txt; head -c 1500 txt/swac.txt; grep -n -a -i -E \"shock|per year|%|0\\.72|5\\.3\" txt/swac.txt | head -80",
  "description": "Extract and inspect the spaceweather.ac.cn PDF"
}

{
  "query": "Jian 2006 Solar Physics 239 337 stream interactions one AU pdf faculty.epss.ucla.edu russell_bib",
  "mode": "standard"
}

{
  "query": "Jian 2008 \"Stream interactions and interplanetary coronal mass ejections at 0.72 AU\" Solar Physics Venus Express Pioneer Venus Orbiter shock",
  "mode": "standard"
}

{
  "query": "Geyer 2021 MAVEN stream interaction regions statistics Mars 1.5 AU solar physics superposed epoch",
  "mode": "standard"
}

{
  "url": "https://link.springer.com/article/10.1007/s11207-006-0132-3",
  "prompt": "Give the full abstract verbatim, and any numbers on SIR count, occurrence per year, shock association percentages (forward, reverse, pairs), and typical peak values (Pt, Np, B, speed increase)."
}

{
  "query": "MAVEN stream interaction regions catalog 2014-2023 185 SIRs shock rate Mars 1.5 au",
  "mode": "standard"
}

{
  "url": "https://arxiv.org/abs/2303.07078",
  "prompt": "Give title, authors, journal reference, and abstract verbatim. Any numbers on SIR counts, occurrence rates, shock fraction at Mars (1.5 AU) compared with 1 AU, and peak parameter values."
}

{
  "url": "https://par.nsf.gov/biblio/10615811",
  "prompt": "Give title, authors, journal, volume, DOI, and the abstract text. Include all numbers given (SIR count, durations, shock counts, predicted shock rate at 1.5 au, compression ratios) and any link to full text."
}

{
  "url": "https://www.aanda.org/articles/aa/full_html/2021/06/aa39833-20/aa39833-20.html",
  "prompt": "Extract quantitative results: number of SIRs/CIRs identified at PSP (orbits 1-5) and the heliocentric distance range, number at 1 AU, fraction with shocks at PSP vs at 1 AU, typical compression (density, B, Pt), and statements about shocks forming at larger distances. Quote verbatim with section/table numbers."
}

{
  "url": "https://par.nsf.gov/servlets/purl/10615811",
  "prompt": "Extract: (a) any table or text compiling SIR shock association rates vs heliocentric distance from 0.1 to 5 au (PSP, Helios, Venus/PVO/VEX 0.72 au, 1 au Wind/ACE/STEREO, Mars 1.5 au, Ulysses 5.3 au) with the cited sources; (b) how the 56% predicted rate at 1.5 au was derived (observed raw rate vs coverage-corrected); (c) peak/median values of Bmax, Npmax, Ptmax, Vmin, Vmax, ΔV, duration at MAVEN vs STEREO-A; (d) compression ratio H values; (e) SIR occurrence rate per year. Quote verbatim with table/figure/section numbers."
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; T=/home/scabot/.claude/projects/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/tool-results; cp $T/webfetch-1792192506533-vq8x7i.pdf $S/pdfs/henderson2025.pdf; cd $S && python3 -I scripts/ex.py pdfs/henderson2025.pdf txt/henderson2025.txt; wc -c txt/henderson2025.txt; grep -n -a -i -E \"shock rate|shock detection|%|au\\)|Table\" txt/henderson2025.txt | head -120",
